(function(){const d=window.DESIGNS;const track=(name,extra={})=>{try{navigator.sendBeacon('/analytics',JSON.stringify({name,path:location.pathname,referrer:document.referrer,utm:Object.fromEntries(new URLSearchParams(location.search)),...extra}))}catch(e){}};document.addEventListener('click',e=>{const a=e.target.closest('[data-design]');if(a)track(a.dataset.outbound?'redbubble_outbound':'design_card_click',{design:a.dataset.design})});track('page_view');window.fc={d,track};})();
